function guideClusterOf(slug) {
  return Object.keys(GUIDE_CLUSTERS).find((key) => GUIDE_CLUSTERS[key].includes(slug)) || null;
}

function relatedGuidesFor(guide, limit = 4) {
  const cluster = guideClusterOf(guide.slug);
  const bySlug = new Map(JOURNAL_SEO_GUIDES.map((item) => [item.slug, item]));
  const picked = [];
  const take = (slugs) => {
    for (const slug of slugs) {
      if (picked.length >= limit) return;
      if (slug === guide.slug || picked.some((item) => item.slug === slug)) continue;
      const match = bySlug.get(slug);
      if (match) picked.push(match);
    }
  };

  // Ротация вместо чтения с начала массива. Раньше take() всегда начинал с
  // первого слага кластера и добирал limit=4 штуки, поэтому в кластере из
  // шести и больше последние статьи не выбирались НИ РАЗУ — например
  // grab-gojek-or-private-driver-bali и bali-layover-day-tour имели ровно по
  // одной входящей ссылке на весь сайт. Начинаем со следующего за собой и
  // идём по кругу: тогда каждая статья кластера получает примерно поровну.
  const rotate = (slugs, from) => {
    const at = slugs.indexOf(from);
    return at < 0 ? slugs : [...slugs.slice(at + 1), ...slugs.slice(0, at)];
  };

  if (cluster) {
    take(rotate(GUIDE_CLUSTERS[cluster], guide.slug));
    const partner = GUIDE_CLUSTERS[GUIDE_CLUSTER_PARTNERS[cluster]] || [];
    // партнёрский кластер сдвигаем на позицию статьи в своём, чтобы соседи
    // не тянули из партнёра одни и те же первые записи
    const offset = Math.max(0, GUIDE_CLUSTERS[cluster].indexOf(guide.slug));
    take(partner.length ? [...partner.slice(offset % partner.length), ...partner.slice(0, offset % partner.length)] : []);
  }
  take(JOURNAL_SEO_GUIDES.map((item) => item.slug));
  return picked.slice(0, limit);
}

function guideArticleRoute(guide) {
  return `${JOURNAL_HUB_ROUTE}/${guide.slug}`;
}

function absoluteGuideArticleUrl(guide) {
  return `${SITE_URL}${guideArticleRoute(guide)}`;
}

function guideArticleFileName(guide) {
  return `bali-journal-guide-${guide.slug}.html`;
}

function buildSeoGuideArticle(guide) {
  const heroTour = tourBySlug(guide.heroTourSlug) || tours[0];
  // Список мест есть не у всякого гайда: разбор пошлины или ответ «можно ли
  // подняться без гида» — сплошной текст без ранжированных карточек. Раньше
  // такой гайд ронял сборку на .map() по undefined; теперь просто нет карточек,
  // а героем страницы становится фото опорного тура (см. heroImage ниже).
  const rankings = (guide.rankings || []).map((item, index) => ({
    ...item,
    position: index + 1,
    image: normalizeJournalImageSrc(item.imageSrc || guidePlaceImage(item.imageTitle || item.name, item.fallbackTourSlug || guide.heroTourSlug)),
  }));
  const leadPlace = rankings[0]?.name || heroTour.title;

  return {
    kind: "guide",
    guide,
    tour: heroTour,
    articleType: { badge: guide.badge, navLabel: guide.navLabel, key: guide.key },
    cardTourLabel: guide.cardTourLabel,
    route: guideArticleRoute(guide),
    url: absoluteGuideArticleUrl(guide),
    title: guide.title,
    description: guide.description,
    excerpt: guide.excerpt,
    sections: guide.sections,
    faq: guide.faq,
    inlineStats: guide.inlineStats,
    rankings,
    heroImage: rankings[0]?.image || publicImagePath(heroTour),
    heroImageAlt: `${leadPlace} in Bali`,
    relatedTours: guide.relatedTourSlugs.map((slug) => tourBySlug(slug)).filter(Boolean),
    relatedGuides: relatedGuidesFor(guide),
  };
}

